cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO quote -- base premiums and processing fee", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("one plain sword -> premium 105 G (100 G base + 5 G fee)");
  it.todo("one plain amulet -> premium 65 G (60 G base + 5 G fee)");
  it.todo("one plain staff -> premium 85 G (80 G base + 5 G fee)");
  it.todo("one plain potion -> premium 45 G (40 G base + 5 G fee)");
  it.todo("one rune -> premium 30 G (25 G base + 5 G fee)");
  it.todo("one moonstone -> premium 30 G (25 G base + 5 G fee)");
  it.todo("sword + amulet -> premium 165 G (100 + 60 base + 5 G fee)");
});

describe("MHPCO quote -- building block of 3 alike components", () => {
  it.todo("2 runes -> base premium 50 G (no block)");
  it.todo("3 runes -> base premium 60 G (block applies)");
  it.todo("4 runes -> base premium 100 G (no block -- block requires exactly 3)");
  it.todo("7 runes -> base premium 175 G (no block -- block requires exactly 3)");
  it.todo("2 runes + 1 moonstone -> base premium 75 G (no block: different types are not alike)");
  it.todo("3 runes + 3 moonstones -> base premium 120 G (two separate blocks, alike = same type)");
  it.todo("3 moonstones -> base premium 60 G (block applies to moonstones too)");
});

describe("MHPCO quote -- item-specific modifiers", () => {
  it.todo("cursed sword, enchantment 3, new customer -> premium 165 G (100 base + 50 curse + 10 first insurance + 5 fee)");
  it.todo("sword with enchantment 5 -> high-enchantment surcharge applies (threshold is >= 5)");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 -> both curse and high-enchantment surcharges apply");
  it.todo("cursed sword (base 100 G) + plain amulet (base 60 G) -> curse adds 50 G (50 % of the cursed item's base premium, not the policy total)");
  it.todo("high-enchantment surcharge applies to the affected item's base premium only, not the policy total");
});

describe("MHPCO quote -- policy-wide modifiers", () => {
  it.todo("customer with exactly 2 years with MHPCO -> 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO -> no loyalty discount");
  it.todo("first quote in a scenario -> 10 % initial assessment surcharge applies");
  it.todo("second quote in a scenario -> 15 % follow-up contract discount applies in addition to the first insurance surcharge");
  it.todo("loyalty, first insurance and follow-up discounts are percentages of the policy base premium (sum of item base premiums)");
  it.todo("the 5 G processing fee is added at the very end, after all percentage modifiers");
});

describe("MHPCO quote -- rounding in the MHPCO's favour", () => {
  it.todo("a premium calculation yielding 197.5 G -> final premium 198 G (rounded up)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
});

describe("MHPCO quote -- integration examples", () => {
  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword, enchantment 3 -> premium 165 G");
  it.todo("3-year customer's second quote, cursed steel sword, enchantment 7 -> premium 160 G");
});

describe("MHPCO quote -- rejections", () => {
  it.todo("quote with an unknown item type (e.g. broomstick) -> throws an Error (adopted reading: Error describing the unknown type; CLI then exits non-zero with the description on stderr)");
});

describe("MHPCO policy -- insurance sum and cap", () => {
  it.todo("policy covering a sword and an amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes -> insurance sum 1750 G, cap 3500 G (block discount affects the premium only)");
  it.todo("policy covering a cursed sword (premium 165 G) -> cap 2000 G (based on the unmodified insurance value)");
});

describe("MHPCO claim -- standard reimbursement and deductible", () => {
  it.todo("regular steel sword, enchantment 3, damage 500 G -> payout 400 G (full reimbursement minus 100 G deductible)");
  it.todo("rune (insurance value 250 G), damage 200 G -> payout 100 G (no enchantment or material, so no special clause)");
  it.todo("dragon attack damaging an insured sword (500 G) and an insured amulet (300 G) -> payout 600 G (deductible applies once per damaged item)");
  it.todo("damage below the deductible -> payout 0 G, never negative");
});

describe("MHPCO claim -- special clauses", () => {
  it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % first, then deductible)");
  it.todo("steel sword, enchantment 8, damage 1000 G -> payout 400 G (threshold is >= 8)");
  it.todo("steel sword, enchantment 7, damage 1000 G -> payout 900 G (no high-enchantment clause)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword, enchantment 8, damage 1000 G -> payout 400 G (high-enchantment clause applies, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (both clauses apply; the 50 % rule wins, then deductible)");
});

describe("MHPCO claim -- rounding in the MHPCO's favour", () => {
  it.todo("a payout calculation yielding 350.5 G -> final payout 350 G (rounded down)");
});

describe("MHPCO claim -- cap exhaustion across successive claims", () => {
  it.todo("sword policy (cap 2000 G), first claim of 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("sword policy (cap 2000 G), second claim of 1500 G -> payout 600 G, remainingCap 0 G (reduced to the remaining cap)");
  it.todo("claim against an already exhausted cap -> payout 0 G, remainingCap 0 G");
});

describe("MHPCO claim -- multiple items of the same type", () => {
  it.todo("policy with two swords, damages with two sword entries -> each entry gets its own deductible");
  it.todo("policy with one sword, damages with two sword entries -> throws an Error (more damage entries of a type than the policy covers; the whole claim is rejected)");
});

describe("MHPCO claim -- rejections", () => {
  it.todo("claim naming an amulet when only a sword is insured -> throws an Error (damaged item not part of the policy)");
  it.todo("claim naming an unknown item type -> throws an Error (damaged item not part of the policy)");
  it.todo("claim with a damage entry amount of -200 -> throws an Error (negative damage amount)");
});

describe("claim-office CLI", () => {
  it.todo("reads the schema example scenario from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout");
  it.todo("a claim step references the policy created by an earlier quote step via its zero-based step index");
  it.todo("exits 0 and writes results for a valid multi-step scenario");
  it.todo("unknown item type in a quote -> exits non-zero, writes an error description to stderr, writes no results to stdout");
  it.todo("damaged item not part of the policy -> exits non-zero and writes an error description to stderr");
  it.todo("negative damage amount -> exits non-zero and writes an error description to stderr");
  it.todo("more sword damages than insured swords -> exits non-zero and writes an error description to stderr");
});
EOF
pnpm test 2>&1 | tail -15

