cat > src/claim-office.ts <<'EOF'
export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const CURSE_SURCHARGE_RATE = 0.5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = ["rune", "moonstone"];

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function qualifiesForComponentBlock(type: string, count: number): boolean {
  return COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE;
}

function basePremiumForGroup(type: string, count: number): number {
  if (qualifiesForComponentBlock(type, count)) {
    return BLOCK_BASE_PREMIUM;
  }
  return count * BASE_PREMIUMS[type];
}

function policyBasePremium(items: Item[]): number {
  let base = 0;
  for (const [type, count] of countByType(items)) {
    base += basePremiumForGroup(type, count);
  }
  return base;
}

function itemRiskSurcharges(items: Item[]): number {
  let surcharges = 0;
  for (const item of items) {
    if (item.cursed === true) {
      surcharges += BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE;
    }
  }
  return surcharges;
}

function roundInOfficesFavour(premium: number): number {
  return Math.ceil(premium);
}

export function quote(customer: Customer, items: Item[]): number {
  const base = policyBasePremium(items);
  const premium =
    base + itemRiskSurcharges(items) + base * FIRST_INSURANCE_SURCHARGE_RATE;
  return roundInOfficesFavour(premium) + PROCESSING_FEE;
}
EOF
